     1→ // @ts-nocheck
     2→// deno-lint-ignore-file no-explicit-any
     3→import { createClient } from "https://esm.sh/@supabase/supabase-js@2.49.2";
     4→import DodoPayments from "https://esm.sh/dodopayments@2.4.1";
     5→
     6→const corsHeaders = {
     7→  "Access-Control-Allow-Origin": "*",
     8→  "Access-Control-Allow-Headers": "authorization, x-client-info, apikey, content-type, webhook-id, webhook-signature, webhook-timestamp",
     9→};
    10→
    11→Deno.serve(async (req) => {
    12→  if (req.method === "OPTIONS") return new Response(null, { headers: corsHeaders });
    13→
    14→  try {
    15→    const SUPABASE_URL = Deno.env.get("SUPABASE_URL")!;
    16→    const SUPABASE_SERVICE_ROLE_KEY = Deno.env.get("SUPABASE_SERVICE_ROLE_KEY")!;
    17→    const DODO_API_KEY = Deno.env.get("DODO_PAYMENTS_API_KEY");
    18→    const WEBHOOK_KEY = Deno.env.get("DODO_PAYMENTS_WEBHOOK_KEY") || Deno.env.get("DODO_PAYMENTS_WEBHOOK_SECRET");
    19→
    20→    if (!DODO_API_KEY) {
    21→      console.error("DODO_PAYMENTS_API_KEY is not configured");
    22→      return new Response("Server misconfigured", { status: 500, headers: corsHeaders });
    23→    }
    24→    if (!WEBHOOK_KEY) {
    25→      console.error("DODO_PAYMENTS_WEBHOOK_KEY/SECRET is not configured");
    26→      return new Response("Server misconfigured", { status: 500, headers: corsHeaders });
    27→    }
    28→
    29→    const rawBody = await req.text();
    30→    const webhookHeaders = {
    31→      "webhook-id": req.headers.get("webhook-id") || "",
    32→      "webhook-signature": req.headers.get("webhook-signature") || "",
    33→      "webhook-timestamp": req.headers.get("webhook-timestamp") || "",
    34→    };
    35→
    36→    const dodo = new DodoPayments({
    37→      bearerToken: DODO_API_KEY,
    38→      webhookKey: WEBHOOK_KEY,
    39→    });
    40→
    41→    let unwrapped: any;
    42→    try {
    43→      unwrapped = dodo.webhooks.unwrap(rawBody, { headers: webhookHeaders });
    44→    } catch (e) {
    45→      console.error("Invalid webhook signature", e);
    46→      return new Response("Invalid signature", { status: 401, headers: corsHeaders });
    47→    }
    48→
    49→    const eventType: string = unwrapped.type || "unknown";
    50→    const payload: Record<string, unknown> = unwrapped.data || {};
    51→    const webhookId = webhookHeaders["webhook-id"];
    52→
    53→    const supabase = createClient(SUPABASE_URL, SUPABASE_SERVICE_ROLE_KEY);
    54→
    55→    // Idempotency: skip if we've already processed this exact webhook-id
    56→    if (webhookId) {
    57→      const { data: dupList } = await supabase
    58→        .from("subscription_webhooks")
    59→        .select("id")
    60→        .eq("gateway", "dodo")
    61→        .eq("webhook_id", webhookId)
    62→        .limit(1);
    63→      if (dupList && dupList.length > 0) {
    64→        console.log(`Duplicate webhook ${webhookId}, skipping`);
    65→        return new Response("OK", { status: 200, headers: corsHeaders });
    66→      }
    67→    }
    68→
    69→    const subscriptionIdForLog = (payload["subscription_id"] as string | undefined) || null;
    70→
    71→    // Log the event (unprocessed)
    72→    const logInsert = await supabase
    73→      .from("subscription_webhooks")
    74→      .insert({
    75→        event_type: eventType,
    76→        payload: unwrapped,
    77→        gateway: "dodo",
    78→        processed: false,
    79→        dodo_subscription_id: subscriptionIdForLog,
    80→        webhook_id: webhookId || null,
    81→      })
    82→      .select("id")
    83→      .single();
    84→
    85→    const logId: string | null = logInsert.data?.id ?? null;
    86→
    87→    async function markProcessed(userId?: string | null) {
    88→      if (!logId) return;
    89→      await supabase
    90→        .from("subscription_webhooks")
    91→        .update({ processed: true, user_id: userId ?? null })
    92→        .eq("id", logId);
    93→    }
    94→
    95→    // Prefer correlation via metadata.local_payment_id (set at checkout creation)
    96→    const meta = (payload["metadata"] as Record<string, string> | undefined) || {};
    97→    const localPaymentId = (meta["local_payment_id"] as string | undefined) || null;
    98→
    99→    if (eventType === "payment.succeeded" || eventType === "payment_succeeded") {
   100→      const paymentId = (payload["payment_id"] as string | undefined) || null;
   101→
   102→      let paymentRow: any = null;
   103→      if (localPaymentId) {
   104→        const { data } = await supabase.from("payments").select("*").eq("id", localPaymentId).single();
   105→        paymentRow = data;
   106→      } else if (paymentId) {
   107→        const { data } = await supabase.from("payments").select("*").eq("dodo_payment_id", paymentId).single();
   108→        paymentRow = data;
   109→      }
   110→
   111→      if (paymentRow) {
   112→        // Persist Dodo payment id and mark as paid
   113→        if (paymentId && !paymentRow.dodo_payment_id) {
   114→          await supabase.from("payments").update({ dodo_payment_id: paymentId }).eq("id", paymentRow.id);
   115→        }
   116→        let newlyPaid = false;
   117→        if (paymentRow.status !== "paid") {
   118→          await supabase.from("payments").update({ status: "paid" }).eq("id", paymentRow.id);
   119→          newlyPaid = true;
   120→        }
   121→
   122→        if (newlyPaid) {
   123→          // Increment credits once (idempotent on status transition)
   124→          const { data: profile } = await supabase
   125→            .from("profiles")
   126→            .select("credits")
   127→            .eq("user_id", paymentRow.user_id)
   128→            .single();
   129→
   130→          if (profile) {
   131→            await supabase
   132→              .from("profiles")
   133→              .update({ credits: profile.credits + paymentRow.credits_purchased })
   134→              .eq("user_id", paymentRow.user_id);
   135→          }
   136→
   137→          // Activate plan if applicable
   138→          if (paymentRow.plan_id) {
   139→            const { data: plan } = await supabase
   140→              .from("plans")
   141→              .select("name, billing_type")
   142→              .eq("id", paymentRow.plan_id)
   143→              .single();
   144→
   145→            if (plan) {
   146→              const endsAt = new Date();
   147→              if (plan.billing_type === "yearly") {
   148→                endsAt.setFullYear(endsAt.getFullYear() + 1);
   149→              } else {
   150→                endsAt.setMonth(endsAt.getMonth() + 1);
   151→              }
   152→              await supabase
   153→                .from("profiles")
   154→                .update({
   155→                  plan: plan.name,
   156→                  subscription_ends_at: endsAt.toISOString(),
   157→                  dodo_subscription_id: (payload["subscription_id"] as string | undefined) || null,
   158→                })
   159→                .eq("user_id", paymentRow.user_id);
   160→            }
   161→          }
   162→        }
   163→
   164→        await markProcessed(paymentRow.user_id);
   165→      }
   166→    } else if (eventType === "payment.failed" || eventType === "payment_failed") {
   167→      const paymentId = (payload["payment_id"] as string | undefined) || null;
   168→      if (localPaymentId) {
   169→        await supabase
   170→          .from("payments")
   171→          .update({ status: "failed", dodo_payment_id: paymentId })
   172→          .eq("id", localPaymentId);
   173→      } else if (paymentId) {
   174→        await supabase.from("payments").update({ status: "failed" }).eq("dodo_payment_id", paymentId);
   175→      }
   176→      await markProcessed(null);
   177→    } else if (eventType === "subscription.renewed" || eventType === "subscription_renewed") {
   178→      const subscriptionId = (payload["subscription_id"] as string | undefined) || null;
   179→      if (subscriptionId) {
   180→        const { data: profile } = await supabase
   181→          .from("profiles")
   182→          .select("user_id, plan, credits")
   183→          .eq("dodo_subscription_id", subscriptionId)
   184→          .single();
   185→
   186→        if (profile) {
   187→          const { data: plan } = await supabase
   188→            .from("plans")
   189→            .select("credits, billing_type")
   190→            .eq("name", profile.plan)
   191→            .single();
   192→
   193→          if (plan) {
   194→            const endsAt = new Date();
   195→            if (plan.billing_type === "yearly") {
   196→              endsAt.setFullYear(endsAt.getFullYear() + 1);
   197→            } else {
   198→              endsAt.setMonth(endsAt.getMonth() + 1);
   199→            }
   200→            await supabase
   201→              .from("profiles")
   202→              .update({
   203→                credits: profile.credits + plan.credits,
   204→                subscription_ends_at: endsAt.toISOString(),
   205→              })
   206→              .eq("user_id", profile.user_id);
   207→          }
   208→        }
   209→      }
   210→      await markProcessed(null);
   211→    } else if (
   212→      eventType === "subscription.cancelled" ||
   213→      eventType === "subscription_cancelled" ||
   214→      eventType === "subscription.on_hold" ||
   215→      eventType === "subscription.failed"
   216→    ) {
   217→      const subscriptionId = (payload["subscription_id"] as string | undefined) || null;
   218→      if (subscriptionId) {
   219→        // For on_hold/failed: downgrade immediately; for cancelled, let expiry task handle downgrade.
   220→        if (eventType.includes("on_hold") || eventType.includes("failed")) {
   221→          await supabase
   222→            .from("profiles")
   223→            .update({
   224→              plan: "free",
   225→              dodo_subscription_id: null,
   226→              subscription_ends_at: null,
   227→            })
   228→            .eq("dodo_subscription_id", subscriptionId);
   229→        }
   230→      }
   231→      await markProcessed(null);
   232→    } else if (eventType === "subscription.active" || eventType === "subscription_active") {
   233→      const subscriptionId = (payload["subscription_id"] as string | undefined) || null;
   234→      if (subscriptionId && localPaymentId) {
   235→        const { data: payment } = await supabase.from("payments").select("user_id").eq("id", localPaymentId).single();
   236→        if (payment) {
   237→          await supabase.from("profiles").update({ dodo_subscription_id: subscriptionId }).eq("user_id", payment.user_id);
   238→          await markProcessed(payment.user_id);
   239→        }
   240→      }
   241→    }
   242→
   243→    return new Response("OK", { status: 200, headers: corsHeaders });
   244→  } catch (err) {
   245→    console.error("dodo-webhook error:", err);
   246→    return new Response("Internal error", { status: 500, headers: corsHeaders });
   247→  }
   248→});
