    29→    const DODO_API_KEY = Deno.env.get("DODO_PAYMENTS_API_KEY");
    30→    const DODO_ENV = Deno.env.get("DODO_PAYMENTS_ENVIRONMENT") || "test_mode";
    31→
    32→    if (!SUPABASE_URL || !SUPABASE_ANON_KEY || !SUPABASE_SERVICE_ROLE_KEY || !DODO_API_KEY) {
    33→      return new Response(JSON.stringify({ error: "Server configuration error" }), {
    34→        status: 500,
    35→        headers: { ...corsHeaders, "Content-Type": "application/json" },
    36→      });
    37→    }
    38→
    39→    const authHeader = req.headers.get("Authorization");
    40→    if (!authHeader) {
    41→      return new Response(JSON.stringify({ error: "Unauthorized" }), {
    42→        status: 401,
    43→        headers: { ...corsHeaders, "Content-Type": "application/json" },
    44→      });
    45→    }
    46→
    47→    const supabaseUser = createClient(SUPABASE_URL, SUPABASE_ANON_KEY, {
    48→      global: { headers: { Authorization: authHeader } },
    49→    });
    50→
    51→    const { data: { user }, error: userError } = await supabaseUser.auth.getUser();
    52→    if (userError || !user) {
