    55→        headers: { ...corsHeaders, "Content-Type": "application/json" },
    56→      });
    57→    }
    58→
    59→    const body = await req.json().catch(() => ({}));
    60→    const paymentId = typeof body.payment_id === "string" ? body.payment_id : null;
    61→    const localPaymentId = typeof body.local_payment_id === "string" ? body.local_payment_id : null;
    62→    const checkoutSessionIdInput = typeof body.checkout_session_id === "string" ? body.checkout_session_id : null;
    63→
    64→    if (!paymentId && !localPaymentId && !checkoutSessionIdInput) {
    65→      return new Response(JSON.stringify({ error: "payment_id, local_payment_id, or checkout_session_id is required" }), {
    66→        status: 400,
    67→        headers: { ...corsHeaders, "Content-Type": "application/json" },
    68→      });
    69→    }
    70→
    71→    const supabase = createClient(SUPABASE_URL, SUPABASE_SERVICE_ROLE_KEY);
    72→
    73→    const baseUrl = DODO_ENV === "live_mode"
    74→      ? "https://live.dodopayments.com"
    75→      : "https://test.dodopayments.com";
    76→
    77→    let dodoPayment: Record<string, any> | null = null;
    78→
    79→    // ── Step 1: find local payment record first ──────────────────────────────
    80→    let paymentRow: Record<string, any> | null = null;
    81→
    82→    if (localPaymentId) {
    83→      const { data } = await supabase
    84→        .from("payments")
    85→        .select("*")
    86→        .eq("id", localPaymentId)
    87→        .eq("user_id", user.id)
    88→        .maybeSingle();
    89→      paymentRow = data || null;
    90→    }
    91→
    92→    if (!paymentId && !paymentRow && checkoutSessionIdInput) {
    93→      const { data } = await supabase
    94→        .from("payments")
    95→        .select("*")
    96→        .eq("dodo_checkout_session_id", checkoutSessionIdInput)
    97→        .eq("user_id", user.id)
    98→        .maybeSingle();
    99→      paymentRow = data || null;
   100→    }
   101→
   102→    // ── Step 2: resolve the Dodo payment_id to call the API ──────────────────
