   105→
   106→    if (dodoPaymentIdToFetch) {
   107→      const paymentResponse = await fetch(`${baseUrl}/payments/${encodeURIComponent(dodoPaymentIdToFetch)}`, {
   108→        method: "GET",
   109→        headers: {
   110→          Authorization: `Bearer ${DODO_API_KEY}`,
   111→          "Content-Type": "application/json",
   112→        },
   113→      });
   114→
   115→      if (paymentResponse.ok) {
   116→        dodoPayment = await paymentResponse.json();
   117→      } else {
   118→        const errorText = await paymentResponse.text();
