   123→    }
   124→
   125→    const resolvedPaymentId = dodoPaymentIdToFetch || dodoPayment?.payment_id || dodoPayment?.id || null;
   126→    const resolvedCheckoutSessionId = checkoutSessionIdInput || dodoPayment?.checkout_session_id || null;
   127→
   128→    // ── Step 3: find by dodo_payment_id or session if still not found ────────
   129→    if (!paymentRow && resolvedPaymentId) {
   130→      const { data } = await supabase
   131→        .from("payments")
   132→        .select("*")
   133→        .eq("dodo_payment_id", resolvedPaymentId)
   134→        .eq("user_id", user.id)
   135→        .maybeSingle();
