   137→    }
   138→
   139→    if (!paymentRow && resolvedCheckoutSessionId) {
   140→      const { data } = await supabase
   141→        .from("payments")
   142→        .select("*")
   143→        .eq("dodo_checkout_session_id", resolvedCheckoutSessionId)
   144→        .eq("user_id", user.id)
   145→        .maybeSingle();
   146→      paymentRow = data || null;
   147→    }
   148→
   149→    if (!paymentRow) {
   150→      return new Response(JSON.stringify({ error: "Payment record not found for current user" }), {
   151→        status: 404,
   152→        headers: { ...corsHeaders, "Content-Type": "application/json" },
   153→      });
   154→    }
   155→
   156→    // If Dodo API was unreachable but webhook already marked it paid, return success immediately
   157→    if (!dodoPayment && paymentRow.status === "paid") {
   158→      return new Response(JSON.stringify({
   159→        success: true,
   160→        local_payment_id: paymentRow.id,
   161→        dodo_payment_id: paymentRow.dodo_payment_id,
   162→        checkout_session_id: paymentRow.dodo_checkout_session_id,
   163→        dodo_status: null,
   164→        local_status: "paid",
   165→        credits_added: false, // already added by webhook
   166→      }), {
   167→        headers: { ...corsHeaders, "Content-Type": "application/json" },
   168→      });
   169→    }
   170→
   171→    const dodoStatus = toLocalStatus(dodoPayment?.status);
   172→    const updatePayload: Record<string, any> = {};
   173→
   174→    if (resolvedPaymentId && paymentRow.dodo_payment_id !== resolvedPaymentId) {
   175→      updatePayload.dodo_payment_id = resolvedPaymentId;
   176→    }
   177→
   178→    if (resolvedCheckoutSessionId && paymentRow.dodo_checkout_session_id !== resolvedCheckoutSessionId) {
   179→      updatePayload.dodo_checkout_session_id = resolvedCheckoutSessionId;
   180→    }
   181→
   182→    if (Object.keys(updatePayload).length > 0) {
   183→      await supabase.from("payments").update(updatePayload).eq("id", paymentRow.id);
   184→    }
   185→
   186→    let becamePaid = false;
   187→    let finalStatus = paymentRow.status;
   188→
   189→    if (dodoStatus === "paid") {
   190→      const { data: paidUpdate } = await supabase
   191→        .from("payments")
   192→        .update({
   193→          status: "paid",
   194→          ...(resolvedPaymentId ? { dodo_payment_id: resolvedPaymentId } : {}),
   195→          ...(resolvedCheckoutSessionId ? { dodo_checkout_session_id: resolvedCheckoutSessionId } : {}),
   196→        })
   197→        .eq("id", paymentRow.id)
   198→        .neq("status", "paid")
   199→        .select("id")
   200→        .maybeSingle();
   201→
   202→      becamePaid = !!paidUpdate;
   203→      finalStatus = "paid";
   204→
   205→      if (becamePaid) {
   206→        const { data: profile } = await supabase
   207→          .from("profiles")
   208→          .select("credits")
   209→          .eq("user_id", paymentRow.user_id)
   210→          .single();
   211→
   212→        if (profile) {
   213→          await supabase
   214→            .from("profiles")
   215→            .update({ credits: profile.credits + paymentRow.credits_purchased })
   216→            .eq("user_id", paymentRow.user_id);
   217→        }
   218→
   219→        if (paymentRow.plan_id) {
   220→          const { data: plan } = await supabase
   221→            .from("plans")
   222→            .select("name, billing_type")
   223→            .eq("id", paymentRow.plan_id)
   224→            .single();
   225→
   226→          if (plan) {
   227→            const endsAt = new Date();
   228→            if (plan.billing_type === "yearly") {
   229→              endsAt.setFullYear(endsAt.getFullYear() + 1);
   230→            } else {
   231→              endsAt.setMonth(endsAt.getMonth() + 1);
   232→            }
   233→
   234→            await supabase
   235→              .from("profiles")
   236→              .update({
   237→                plan: plan.name,
   238→                subscription_ends_at: endsAt.toISOString(),
   239→                ...(dodoPayment?.subscription_id ? { dodo_subscription_id: dodoPayment.subscription_id } : {}),
   240→              })
   241→              .eq("user_id", paymentRow.user_id);
   242→          }
   243→        }
   244→      }
   245→    } else if (dodoStatus && dodoStatus !== paymentRow.status) {
   246→      await supabase
   247→        .from("payments")
   248→        .update({ status: dodoStatus })
   249→        .eq("id", paymentRow.id);
   250→      finalStatus = dodoStatus;
   251→    }
   252→
   253→    return new Response(JSON.stringify({
   254→      success: true,
   255→      local_payment_id: paymentRow.id,
   256→      dodo_payment_id: resolvedPaymentId,
   257→      checkout_session_id: resolvedCheckoutSessionId,
   258→      dodo_status: dodoPayment?.status || null,
   259→      local_status: finalStatus,
   260→      credits_added: becamePaid,
   261→    }), {
   262→      headers: { ...corsHeaders, "Content-Type": "application/json" },
   263→    });
   264→  } catch (err: unknown) {
   265→    console.error("verify-dodo-payment error:", err);
   266→    return new Response(JSON.stringify({ error: err instanceof Error ? err.message : String(err) }), {
   267→      status: 500,
   268→      headers: { ...corsHeaders, "Content-Type": "application/json" },
   269→    });
   270→  }
   271→});
